const e="chavara-youth-fest-yuva",d=2024,n="Built from the YUVA 2024 guidelines (Chavara Youth, Kristu Jayanti College, Bengaluru). The guidelines print no age groups, no judging marks and no points table; prizes are cash only. Bank account and UPI details are printed in the guidelines and are not copied; payment is by bank transfer or UPI. The guidelines also name student coordinators for each event with phone numbers; only the two main contacts are kept as variables and the coordinator names are listed in each competition. Dates and fees are the 2024 edition and are the starting suggestion for a later edition. Quiz has no stated time limit.",i={Title:"Rules & Criteria",Subtitle:"YUVA (Youth United for Visionary Actions) - a global fest of literary and cultural competitions by Chavara Youth, Kristu Jayanti College, Bengaluru",NoticeTitle:"Please Read Before Registering",Notice:"Registration closes on {{RegistrationEnd}}. Entries are sent through the Google Form. Preliminary rounds are online; finals are on campus.",Notes:["Theme for the year: Youth and the Church.","Late submissions are not accepted."],Sections:[{Key:"general",Title:"General",Items:["YUVA is an initiative of Chavara Youth, a Catholic organisation under the Jayantian Catholic Association of Kristu Jayanti College, Bengaluru.","YUVA brings together Catholic youth around the world and gives young people a place to show their talents.","The theme for this year is 'Youth and the Church'.","The programme has individual and group events.","Entries can be submitted in English, Hindi, Kannada, Malayalam or Tamil.","There are two rounds for each event: the preliminary round is online and the final round is on campus, offline.","Both the preliminary and the final rounds are online for international participants.","All details about the fest are on the official Instagram page (@chavara_youth) and the official website."]},{Key:"eligibility",Title:"Who may enter",Items:["The participant must be a member of a youth organisation of a parish or of an educational institution.","There is no limit on the number of entries for individual events from one parish or organisation.","A team of members of one parish or organisation may register together for a fixed amount (see fees).","No age limit is printed in the guidelines."]},{Key:"registration",Title:"How to register",Items:["Registration and submission are done through Google Forms.","Registration opens on {{RegistrationStart}} and ends on {{RegistrationEnd}}.","Preliminary round submissions are accepted from {{PrelimStart}} to {{PrelimEnd}}.","Follow the deadline given in the guidelines of each event. Late submissions are not accepted.","For the preliminary round, every entry submitted by the participant must be recorded.","Name each submission as ChestNumber_EventName, for example EE01_Elocution."]},{Key:"fees",Title:"Fees and payment",Items:["Participants pay a small registration fee for both individual and group events: {{EntryFee}}.","A team of members of one parish or organisation may instead pay one fixed amount: {{TeamFee}}.","Payment is made by bank transfer or UPI. The account details are printed in the guidelines and are not repeated here."]},{Key:"dates",Title:"Dates",Items:["Registration: {{RegistrationStart}} to {{RegistrationEnd}}.","Preliminary round submissions: {{PrelimStart}} to {{PrelimEnd}}.","Preliminary round results: {{PrelimResults}}.","Final rounds and valedictory ceremony: {{FinalDate}}."]},{Key:"venue",Title:"Venue",Items:["The final rounds and the valedictory ceremony are held at {{Venue}}."]},{Key:"levels",Title:"Rounds and qualification",Items:["Each event has a preliminary round (online) and a final round (on campus, offline).","Teams that qualify for the final round take care of their own transport and stay. The organiser gives help if it is needed.","The final round for international participants is online."]},{Key:"conduct",Title:"Conduct",Items:["Plagiarism in literary events is not encouraged. A plagiarised submission is disqualified.","The copyright of all submissions stays with the organisers.","Entries of the finalists are uploaded on the official Instagram page (@chavara_youth) and the official website."]},{Key:"prizes",Title:"Prizes and recognition",Items:["Winners share cash prizes worth {{TotalPrize}}.","Group events: 1st prize {{GroupPrize1}}, 2nd prize {{GroupPrize2}}, 3rd prize {{GroupPrize3}}.","Individual events: 1st prize {{IndPrize1}}, 2nd prize {{IndPrize2}}, 3rd prize {{IndPrize3}}.","All participants receive e-certificates.","Overall winners and runners-up receive trophies and certificates. Winners receive the cash prize, a trophy and a certificate."]},{Key:"teams",Title:"Teams",Items:["Group events are open to teams from a parish or an organisation; the team size for each event is given with the event."]},{Key:"other",Title:"Other",Items:["Contact: chavarayouth@kristujayanti.com, www.chavarayouth.com, Instagram @chavara_youth."]}],Documents:[{Title:"YUVA 2024 guidelines",Url:"https://www.scribd.com/document/748753943/YUVA-Guidelines"},{Title:"Registration form",Url:"https://forms.gle/ZSf4Se12qCCbfiUJ9"},{Title:"Chavara Youth website",Url:"https://www.chavarayouth.com/"}]},t=[{ParticipantType:"Team",Source:"YUVA 2024 guidelines - group events",Sections:{About:null,TimeAndFormat:null,Rules:["Group events are Group Dance, Group Song and Quiz."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:["Teams of one parish or organisation can register together for the fixed team amount."]},Markdown:`## Rules
- Group events are Group Dance, Group Song and Quiz.

## Notes for participants
- Teams of one parish or organisation can register together for the fixed team amount.`}],o=[],a=JSON.parse('[{"Title":"Solo Dance","Source":"YUVA 2024 guidelines - Solo Dance","Sections":{"About":null,"TimeAndFormat":["Duration is 2 to 4 minutes.","Send the video in landscape mode.","The file is MP4, at most 500 MB."],"Rules":["The theme is based on Christianity.","Contact the event coordinators for questions (Ms. Anu Mary Raju and Mr. Milton Joseph)."],"Allowed":["Only Christian devotional songs, Gospel songs or instrumental music.","Costumes and props.","Cutting and merging of clips."],"NotAllowed":["Vulgarity: the dress must be modest and presentable.","Special effects.","Applause or hooting sound effects in the audio."],"Judging":["Song selection.","Adherence to the theme.","Choreography.","Synchronization.","Overall performance."],"Points":null,"Notes":["Keep the original video until the results are out.","Submission link: https://forms.gle/4i4N8M3FnveQdiwK6"]},"Markdown":"## Time and format\\n- Duration is 2 to 4 minutes.\\n- Send the video in landscape mode.\\n- The file is MP4, at most 500 MB.\\n\\n## Rules\\n- The theme is based on Christianity.\\n- Contact the event coordinators for questions (Ms. Anu Mary Raju and Mr. Milton Joseph).\\n\\n## Allowed\\n- Only Christian devotional songs, Gospel songs or instrumental music.\\n- Costumes and props.\\n- Cutting and merging of clips.\\n\\n## Not allowed\\n- Vulgarity: the dress must be modest and presentable.\\n- Special effects.\\n- Applause or hooting sound effects in the audio.\\n\\n## Judging\\n- Song selection.\\n- Adherence to the theme.\\n- Choreography.\\n- Synchronization.\\n- Overall performance.\\n\\n## Notes for participants\\n- Keep the original video until the results are out.\\n- Submission link: https://forms.gle/4i4N8M3FnveQdiwK6"},{"Title":"Solo Song","Source":"YUVA 2024 guidelines - Solo Song","Sections":{"About":null,"TimeAndFormat":["Duration is 2 to 4 minutes.","Send a landscape video of the participant singing.","The file is MP4, at most 500 MB."],"Rules":["Only Christian devotional songs, in Malayalam, Kannada, Tamil, English or Hindi. Syrian songs are also allowed.","A studio recorded entry is also encouraged, but a video of the participant singing must be made.","Contact the event coordinators for questions (Ms. Ann Mary Joy and Mr. Tom Zacharias)."],"Allowed":["Karaoke or instruments and accompanists.","Editing of the video."],"NotAllowed":["Dress that is not modest."],"Judging":["Song selection.","Harmony.","Clarity.","Voice modulation.","Overall performance."],"Points":null,"Notes":["Keep the original video."]},"Markdown":"## Time and format\\n- Duration is 2 to 4 minutes.\\n- Send a landscape video of the participant singing.\\n- The file is MP4, at most 500 MB.\\n\\n## Rules\\n- Only Christian devotional songs, in Malayalam, Kannada, Tamil, English or Hindi. Syrian songs are also allowed.\\n- A studio recorded entry is also encouraged, but a video of the participant singing must be made.\\n- Contact the event coordinators for questions (Ms. Ann Mary Joy and Mr. Tom Zacharias).\\n\\n## Allowed\\n- Karaoke or instruments and accompanists.\\n- Editing of the video.\\n\\n## Not allowed\\n- Dress that is not modest.\\n\\n## Judging\\n- Song selection.\\n- Harmony.\\n- Clarity.\\n- Voice modulation.\\n- Overall performance.\\n\\n## Notes for participants\\n- Keep the original video."},{"Title":"Group Dance","Source":"YUVA 2024 guidelines - Group Dance","Sections":{"About":null,"TimeAndFormat":["Duration is 2 to 4 minutes.","Team of 6 to 10 members.","Landscape video with proper lighting.","The file is MP4, at most 500 MB."],"Rules":["The theme is Christianity.","Only Christian devotional songs, Gospel songs or instrumental music.","The dancers and props must be visible in the frame.","Audio must be good.","Contact the event coordinators for questions (Ms. Theres Emmanuel and Mr. Anosh Paul K)."],"Allowed":["Costumes and props.","Editing of the video."],"NotAllowed":["Vulgarity: the dress must be modest.","Sound effects."],"Judging":["Song selection.","Adherence to the theme.","Choreography.","Synchronisation.","Overall performance."],"Points":null,"Notes":["Keep the original video."]},"Markdown":"## Time and format\\n- Duration is 2 to 4 minutes.\\n- Team of 6 to 10 members.\\n- Landscape video with proper lighting.\\n- The file is MP4, at most 500 MB.\\n\\n## Rules\\n- The theme is Christianity.\\n- Only Christian devotional songs, Gospel songs or instrumental music.\\n- The dancers and props must be visible in the frame.\\n- Audio must be good.\\n- Contact the event coordinators for questions (Ms. Theres Emmanuel and Mr. Anosh Paul K).\\n\\n## Allowed\\n- Costumes and props.\\n- Editing of the video.\\n\\n## Not allowed\\n- Vulgarity: the dress must be modest.\\n- Sound effects.\\n\\n## Judging\\n- Song selection.\\n- Adherence to the theme.\\n- Choreography.\\n- Synchronisation.\\n- Overall performance.\\n\\n## Notes for participants\\n- Keep the original video."},{"Title":"Group Song","Source":"YUVA 2024 guidelines - Group Song","Sections":{"About":null,"TimeAndFormat":["Duration is 2 to 4 minutes.","Team of 6 to 12 members, including instrumentalists.","The file is MP4, at most 500 MB."],"Rules":["Only Christian devotional songs, in Malayalam, Tamil, Hindi, Kannada or English. Syrian songs are allowed.","A studio recorded entry is encouraged.","Contact the event coordinators for questions (Ms. Jikki M Roy and Ms. Treesa Benny)."],"Allowed":["Karaoke or instruments.","Editing of the video."],"NotAllowed":["Dress that is not modest."],"Judging":["Song selection.","Harmony.","Clarity.","Voice modulation.","Overall performance."],"Points":null,"Notes":["Keep the original video."]},"Markdown":"## Time and format\\n- Duration is 2 to 4 minutes.\\n- Team of 6 to 12 members, including instrumentalists.\\n- The file is MP4, at most 500 MB.\\n\\n## Rules\\n- Only Christian devotional songs, in Malayalam, Tamil, Hindi, Kannada or English. Syrian songs are allowed.\\n- A studio recorded entry is encouraged.\\n- Contact the event coordinators for questions (Ms. Jikki M Roy and Ms. Treesa Benny).\\n\\n## Allowed\\n- Karaoke or instruments.\\n- Editing of the video.\\n\\n## Not allowed\\n- Dress that is not modest.\\n\\n## Judging\\n- Song selection.\\n- Harmony.\\n- Clarity.\\n- Voice modulation.\\n- Overall performance.\\n\\n## Notes for participants\\n- Keep the original video."},{"Title":"Photography","Source":"YUVA 2024 guidelines - Photography","Sections":{"About":["Theme: Joy of Charity."],"TimeAndFormat":["Send one photograph and a caption.","The file is JPG, at most 100 MB."],"Rules":["The photograph must show the theme.","DSLR and mobile cameras are accepted.","Contact the event coordinators for questions (Ms. Elizabeth Giji and Mr. Noyal Mathew)."],"Allowed":["Cropping."],"NotAllowed":["Watermarks, text or graphics.","Editing, post processing or manipulation."],"Judging":["Adherence to the theme.","Light and exposure.","Clarity and creativity.","Overall performance.","Caption."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Theme: Joy of Charity.\\n\\n## Time and format\\n- Send one photograph and a caption.\\n- The file is JPG, at most 100 MB.\\n\\n## Rules\\n- The photograph must show the theme.\\n- DSLR and mobile cameras are accepted.\\n- Contact the event coordinators for questions (Ms. Elizabeth Giji and Mr. Noyal Mathew).\\n\\n## Allowed\\n- Cropping.\\n\\n## Not allowed\\n- Watermarks, text or graphics.\\n- Editing, post processing or manipulation.\\n\\n## Judging\\n- Adherence to the theme.\\n- Light and exposure.\\n- Clarity and creativity.\\n- Overall performance.\\n- Caption."},{"Title":"Pencil Sketching","Source":"YUVA 2024 guidelines - Pencil Sketching","Sections":{"About":["Theme: You are not Alone."],"TimeAndFormat":["Use a white A3 or A4 sheet.","The file is JPG, 10 MB.","A time-lapse video of the participant drawing (face and work visible) is asked for at evaluation, MP4, 500 MB."],"Rules":["Black and white work with black pencils only.","Plagiarism disqualifies the entry.","Contact the event coordinators for questions (Ms. Sera Tisa and Mr. Chacko Kallivayalli)."],"Allowed":null,"NotAllowed":null,"Judging":["Adherence to the theme.","Creativity.","Originality.","Artistic composition.","Overall impression."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Theme: You are not Alone.\\n\\n## Time and format\\n- Use a white A3 or A4 sheet.\\n- The file is JPG, 10 MB.\\n- A time-lapse video of the participant drawing (face and work visible) is asked for at evaluation, MP4, 500 MB.\\n\\n## Rules\\n- Black and white work with black pencils only.\\n- Plagiarism disqualifies the entry.\\n- Contact the event coordinators for questions (Ms. Sera Tisa and Mr. Chacko Kallivayalli).\\n\\n## Judging\\n- Adherence to the theme.\\n- Creativity.\\n- Originality.\\n- Artistic composition.\\n- Overall impression."},{"Title":"Essay Writing","Source":"YUVA 2024 guidelines - Essay writing","Sections":{"About":["Theme: The Church as a Catalyst in Youth."],"TimeAndFormat":["800 to 1000 words.","Typed, or written and scanned.","The file is PDF only, at most 100 MB."],"Rules":["The essay can be in English, Hindi, Kannada, Tamil or Malayalam.","Plagiarism, cuss words or foul language disqualify the entry.","Contact the event coordinators for questions (Ms. Stemi George and Mr. Akash Mathew)."],"Allowed":null,"NotAllowed":null,"Judging":["Adherence to the theme.","Content and originality.","Language.","Overall impact."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Theme: The Church as a Catalyst in Youth.\\n\\n## Time and format\\n- 800 to 1000 words.\\n- Typed, or written and scanned.\\n- The file is PDF only, at most 100 MB.\\n\\n## Rules\\n- The essay can be in English, Hindi, Kannada, Tamil or Malayalam.\\n- Plagiarism, cuss words or foul language disqualify the entry.\\n- Contact the event coordinators for questions (Ms. Stemi George and Mr. Akash Mathew).\\n\\n## Judging\\n- Adherence to the theme.\\n- Content and originality.\\n- Language.\\n- Overall impact."},{"Title":"Elocution","Source":"YUVA 2024 guidelines - Elocution","Sections":{"About":["Theme: Sentire Cum Ecclesia - Thinking and Feeling with the Church."],"TimeAndFormat":["Duration is 2 to 4 minutes.","Landscape video.","The file is MP4, at most 500 MB."],"Rules":["Speak in English, Hindi, Tamil, Kannada or Malayalam.","Record the whole speech without editing.","The voice must be clear and audible.","Speak without reading from papers, notes or cards.","Dress modestly.","Contact the event coordinators for questions (Ms. Anna Lijo and Mr. Gladson Shaji Chittilapilly)."],"Allowed":null,"NotAllowed":null,"Judging":["Adherence to the theme.","Content and articulation of ideas.","Oratory skills.","Expression.","Presentation and overall performance."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Theme: Sentire Cum Ecclesia - Thinking and Feeling with the Church.\\n\\n## Time and format\\n- Duration is 2 to 4 minutes.\\n- Landscape video.\\n- The file is MP4, at most 500 MB.\\n\\n## Rules\\n- Speak in English, Hindi, Tamil, Kannada or Malayalam.\\n- Record the whole speech without editing.\\n- The voice must be clear and audible.\\n- Speak without reading from papers, notes or cards.\\n- Dress modestly.\\n- Contact the event coordinators for questions (Ms. Anna Lijo and Mr. Gladson Shaji Chittilapilly).\\n\\n## Judging\\n- Adherence to the theme.\\n- Content and articulation of ideas.\\n- Oratory skills.\\n- Expression.\\n- Presentation and overall performance."},{"Title":"Quiz","Source":"YUVA 2024 guidelines - Quiz","Sections":{"About":["Syllabus: Gospel of St. Luke 40 percent (POC/NRSV), YOUCAT 30 percent, History of the Catholic Church 10 percent, Life of St. Kuriakose Elias Chavara 10 percent, Catholic teachings related to youth 10 percent."],"TimeAndFormat":["A team has three members.","Preliminary round: 50 objective questions with four options each, on Google Forms.","Final round: offline on campus."],"Rules":["The preliminary quiz links are shared on a WhatsApp group after registration.","Questions left unattended get no marks.","There is no negative marking.","Malpractice may lead to disqualification.","Contact the event coordinators for questions (Mr. Alan Sunny, Ms. Ann Kochikunnel, Mr. Milan Donson and Ms. Sania Johnson)."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Syllabus: Gospel of St. Luke 40 percent (POC/NRSV), YOUCAT 30 percent, History of the Catholic Church 10 percent, Life of St. Kuriakose Elias Chavara 10 percent, Catholic teachings related to youth 10 percent.\\n\\n## Time and format\\n- A team has three members.\\n- Preliminary round: 50 objective questions with four options each, on Google Forms.\\n- Final round: offline on campus.\\n\\n## Rules\\n- The preliminary quiz links are shared on a WhatsApp group after registration.\\n- Questions left unattended get no marks.\\n- There is no negative marking.\\n- Malpractice may lead to disqualification.\\n- Contact the event coordinators for questions (Mr. Alan Sunny, Ms. Ann Kochikunnel, Mr. Milan Donson and Ms. Sania Johnson)."}]'),r=[],s=[{Key:"RegistrationStart",Kind:"date",Label:"Registration opens",Value:"2024-01-10",Source:"YUVA 2024 guidelines - Registration"},{Key:"RegistrationEnd",Kind:"date",Label:"Last date to register",Value:"2024-02-25",Source:"YUVA 2024 guidelines - Registration"},{Key:"PrelimStart",Kind:"date",Label:"Preliminary round submissions begin",Value:"2024-01-15",Source:"YUVA 2024 guidelines - Registration"},{Key:"PrelimEnd",Kind:"date",Label:"Preliminary round submissions end",Value:"2024-02-29",Source:"YUVA 2024 guidelines - Registration"},{Key:"PrelimResults",Kind:"date",Label:"Preliminary round results",Value:"2024-03-20",Source:"YUVA 2024 guidelines - Registration"},{Key:"FinalDate",Kind:"date",Label:"Final rounds and valedictory ceremony",Value:"2024-04-14",Source:"YUVA 2024 guidelines - Registration"},{Key:"Venue",Kind:"address",Label:"Final round venue",Value:{Name:"Kristu Jayanti College, Central Campus",Address:"",City:"Bengaluru",MapUrl:"",Directions:""},Source:"YUVA 2024 guidelines - Registration"},{Key:"EntryFee",Kind:"fee",Label:"Entry fee",Value:"Rs 100 for each individual event and Rs 250 for each group event",Source:"YUVA 2024 guidelines - Registration"},{Key:"TeamFee",Kind:"fee",Label:"Fixed team fee",Value:"Rs 1500 for a team of one parish or organisation",Source:"YUVA 2024 guidelines - General guidelines"},{Key:"TotalPrize",Kind:"prize",Label:"Total cash prizes",Value:"INR 2,00,000",Source:"YUVA 2024 guidelines - General guidelines"},{Key:"GroupPrize1",Kind:"prize",Label:"Group event 1st prize",Value:"Rs 15000",Source:"YUVA 2024 guidelines - Prizes"},{Key:"GroupPrize2",Kind:"prize",Label:"Group event 2nd prize",Value:"Rs 10000",Source:"YUVA 2024 guidelines - Prizes"},{Key:"GroupPrize3",Kind:"prize",Label:"Group event 3rd prize",Value:"Rs 5000",Source:"YUVA 2024 guidelines - Prizes"},{Key:"IndPrize1",Kind:"prize",Label:"Individual event 1st prize",Value:"Rs 5000",Source:"YUVA 2024 guidelines - Prizes"},{Key:"IndPrize2",Kind:"prize",Label:"Individual event 2nd prize",Value:"Rs 3000",Source:"YUVA 2024 guidelines - Prizes"},{Key:"IndPrize3",Kind:"prize",Label:"Individual event 3rd prize",Value:"Rs 2000",Source:"YUVA 2024 guidelines - Prizes"},{Key:"Contact1",Kind:"contact",Label:"Contact for questions",Value:{Name:"Ms. Megha Mary",Role:"Contact person",Phone:"6202471441",WhatsApp:"",Email:"chavarayouth@kristujayanti.com"},Source:"YUVA 2024 guidelines - Contact Details"},{Key:"Contact2",Kind:"contact",Label:"Second contact for questions",Value:{Name:"Mr. Boffin Sunny",Role:"Contact person",Phone:"9400047189",WhatsApp:"",Email:"chavarayouth@kristujayanti.com"},Source:"YUVA 2024 guidelines - Contact Details"}],l=[{Claim:"Rules, dates, fees, prizes and event rules are from the organiser's own YUVA 2024 guidelines.",SourceType:"Primary - the event's own rules document",Source:"YUVA 2024 Guidelines, Chavara Youth, Kristu Jayanti College",Url:"https://www.scribd.com/document/748753943/YUVA-Guidelines"}],u={TemplateKey:e,Year:2024,Note:n,Page:i,ParticipantTypes:t,AgeGroups:o,Competitions:a,CompetitionAgeGroups:r,Variables:s,Evidence:l};export{o as AgeGroups,r as CompetitionAgeGroups,a as Competitions,l as Evidence,n as Note,i as Page,t as ParticipantTypes,e as TemplateKey,s as Variables,d as Year,u as default};
